using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Helm of Brilliance (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class HelmOfBrilliance2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("helm-of-brilliance", null, 0, MagicItemType.WondrousItem, ItemRarity.VeryRare, true, ContentSource.Srd51,
			Magic(Resist(DamageType.Fire)),
			("Elmo della luminosità", "Oggetto meraviglioso, molto raro (richiede sintonia)",
			"In questo elmo scintillante sono stati incastonati 1d10 diamanti, 2d10 rubini, 3d10 opali di fuoco e 4d10 opali. Se staccate dall'elmo, le gemme diventano polvere. Quando tutte le gemme sono state rimosse o distrutte, l'elmo perde la sua magia.\n\nFinché il personaggio lo indossa, ottiene i benefici seguenti:\n\n- Può usare un'azione per lanciare uno degli incantesimi seguenti (CD del tiro salvezza 18), usando una gemma del tipo specificato come componente: *luce diurna* (opale), *muro di fuoco* (rubino), *palla di fuoco* (opale di fuoco) o *spruzzo prismatico* (diamante). Non appena lanciato l'incantesimo, la gemma viene distrutta e scompare dall'elmo.\n\n- Finché rimane incastonato almeno un diamante, l'elmo emana luce fioca in un raggio di 9 metri quando almeno un non morto si trova in quell'area. Ogni non morto che inizia il suo turno in quell'area subisce 1d6 danni radiosi.\n\n- Finché rimane incastonato almeno un rubino, il personaggio ottiene resistenza ai danni da fuoco.\n\n- Finché rimane incastonato almeno un'opale di fuoco, il personaggio può usare un'azione per pronunciare una parola d'ordine e generare fiamme intorno a una delle armi che impugna. Le fiamme proiettano luce intensa in un raggio di 3 metri e luce fioca per altri 3 metri. Le fiamme non danneggiano né il personaggio, né l'arma. Quando il personaggio colpisce con un attacco sferrato con l'arma fiammeggiante, infligge al bersaglio 1d6 danni da fuoco extra. Le fiamme permangono finché il personaggio non usa un'azione bonus per pronunciare nuovamente la parola d'ordine, finché non lascia cadere l'arma o finché non la rinfodera.\n\nIl personaggio tira un d20 se indossa l'elmo e subisce danni da fuoco per avere fallito un tiro salvezza contro un incantesimo. Se ottiene come risultato 1, le gemme rimaste sull'elmo irradiano raggi di luce. Ogni creatura situata entro 18 metri dall'elmo, a eccezione del personaggio, deve superare un tiro salvezza su Destrezza con CD 17, altrimenti viene colpita da un raggio e subisce un ammontare di danni radiosi pari al numero di gemme rimaste sull'elmo. Subito dopo, sia l'elmo che le gemme vengono distrutti."),
			("Helm of Brilliance", "Wondrous item, very rare (requires attunement)",
			"This dazzling helm is set with 1d10 diamonds, 2d10 rubies, 3d10 fire opals, and 4d10 opals. Any gem pried from the helm crumbles to dust. When all the gems are removed or destroyed, the helm loses its magic.\n\nYou gain the following benefits while wearing it:\n\nYou can use an action to cast one of the following spells (save DC 18), using one of the helm's gems of the specified type as a component: daylight (opal), fireball (fire opal), prismatic spray (diamond), or wall of fire (ruby). The gem is destroyed when the spell is cast and disappears from the helm.\n\nAs long as it has at least one diamond, the helm emits dim light in a 30-foot radius when at least one undead is within that area. Any undead that starts its turn in that area takes 1d6 radiant damage.\n\nAs long as the helm has at least one ruby, you have resistance to fire damage.\n\nAs long as the helm has at least one fire opal, you can use an action and speak a command word to cause one weapon you are holding to burst into flames. The flames emit bright light in a 10-foot radius and dim light for an additional 10 feet. The flames are harmless to you and the weapon. When you hit with an attack using the blazing weapon, the target takes an extra 1d6 fire damage. The flames last until you use a bonus action to speak the command word again or until you drop or stow the weapon.\n\nRoll a d20 if you are wearing the helm and take fire damage as a result of failing a saving throw against a spell. On a roll of 1, the helm emits beams of light from its remaining gems. Each creature within 60 feet of the helm other than you must succeed on a DC 17 Dexterity saving throw or be struck by a beam, taking radiant damage equal to the number of gems in the helm. The helm and its gems are then destroyed.", null));
	}
}
